package com.hbm.client.silex;
import com.hbm.client.gui.LegacyContainerScreen;import com.hbm.fluid.HbmFluids;import com.hbm.item.fluid.client.FluidInfo;import com.hbm.machine.silex.*;import com.mojang.blaze3d.systems.RenderSystem;import com.mojang.blaze3d.vertex.*;import java.util.*;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.renderer.GameRenderer;import net.minecraft.client.resources.sounds.SimpleSoundInstance;import net.minecraft.network.chat.Component;import net.minecraft.sounds.SoundEvents;import net.minecraft.world.entity.player.Inventory;import net.neoforged.neoforge.network.PacketDistributor;

/** Exact176x222 source GUI, real world-tick wavelength trace and both distinct fluid resources. */
public final class SilexScreen extends LegacyContainerScreen<SilexMenu> {
 public SilexScreen(SilexMenu menu,Inventory player,Component title){super(menu,player,title,SilexContent.id("textures/gui/processing/gui_silex.png"),176,222);}
 private SilexBlockEntity machine(){return minecraft!=null&&minecraft.level!=null&&minecraft.level.getBlockEntity(menu.position()) instanceof SilexBlockEntity machine?machine:null;}
 @Override protected void renderLabels(GuiGraphics graphics,int x,int y){graphics.drawString(font,title,34-font.width(title)/2,8,4210752,false);graphics.drawString(font,playerInventoryTitle,8,128,4210752,false);var machine=machine();if(machine!=null&&machine.mode!=LaserWavelength.NULL){var name=Component.translatable(machine.mode.nameKey).withStyle(machine.mode.textColor);graphics.drawString(font,name,132-font.width(name)/2,16,0,false);}}
 @Override protected void renderBg(GuiGraphics graphics,float partial,int x,int y){super.renderBg(graphics,partial,x,y);var machine=machine();if(machine==null)return;
  if(machine.mode!=LaserWavelength.NULL){float frequency=.1F*(float)Math.pow(2,machine.mode.ordinal());int color=machine.mode==LaserWavelength.VISIBLE?java.awt.Color.HSBtoRGB(machine.getLevel().getGameTime()/50F,.5F,1F)&16777215:machine.mode.guiColor;wave(graphics,machine.getLevel().getGameTime(),frequency,color);}
  if(machine.tank.getFill()>0)drawLegacyRegion(graphics,7,41,176,machine.tank.getTankType()==HbmFluids.PEROXIDE||machine.fluidConvertible()?118:109,54,9);
  if(!machine.current.isEmpty()&&machine.progress>0)drawLegacyRegion(graphics,45,82,176,0,machine.progress*69/SilexBlockEntity.PROCESS_TIME,43);
  int fill=machine.currentFill*52/SilexBlockEntity.MAX_FILL;if(fill>0)drawLegacyRegion(graphics,26,124-fill,176,109-fill,16,fill);
  int fluid=machine.tank.getFill()*52/Math.max(machine.tank.getMaxFill(),1);if(fluid>0)drawLegacyRegion(graphics,8,42,176,machine.tank.getTankType()==HbmFluids.PEROXIDE?43:50,fluid,7);
 }
 private void wave(GuiGraphics graphics,long time,float frequency,int color){graphics.flush();RenderSystem.setShader(GameRenderer::getPositionColorShader);RenderSystem.disableBlend();RenderSystem.lineWidth(3);var vertices=Tesselator.getInstance().begin(VertexFormat.Mode.DEBUG_LINES,DefaultVertexFormat.POSITION_COLOR);var pose=graphics.pose().last().pose();float offset=(float)((float)time%(4*Math.PI/frequency));for(int i=1;i<84/.5F;i++){double currentX=offset+81+i*.5F,nextX=offset+81+(i+1)*.5F,currentY=46+8*Math.sin(frequency*currentX),nextY=46+8*Math.sin(frequency*nextX);vertices.addVertex(pose,(float)(leftPos+currentX-offset),(float)(topPos+currentY),0).setColor(color>>16&255,color>>8&255,color&255,255);vertices.addVertex(pose,(float)(leftPos+nextX-offset),(float)(topPos+nextY),0).setColor(color>>16&255,color>>8&255,color&255,255);}BufferUploader.drawWithShader(vertices.buildOrThrow());RenderSystem.lineWidth(1);}
 @Override public void render(GuiGraphics graphics,int x,int y,float partial){super.render(graphics,x,y,partial);var machine=machine();if(machine==null)return;if(legacyInfoHovered(x,y,8,42,52,7)){var lines=new ArrayList<Component>();lines.add(machine.tank.getTankType().displayName());lines.add(Component.literal(machine.tank.getFill()+"/"+machine.tank.getMaxFill()+"mB"));if(machine.tank.getPressure()!=0){lines.add(Component.translatable("gui.hbm.chemical.pressure",machine.tank.getPressure()).withStyle(net.minecraft.ChatFormatting.RED));lines.add(Component.translatable("gui.hbm.chemical.pressurized").withStyle(net.minecraft.ChatFormatting.DARK_RED));}FluidInfo.append(machine.tank.getTankType(),lines,hasShiftDown());graphics.renderComponentTooltip(font,lines,x,y);}if(!machine.current.isEmpty()&&legacyInfoHovered(x,y,27,72,16,52))graphics.renderComponentTooltip(font,List.of(Component.literal(machine.currentFill+"/16000mB"),machine.current.getHoverName()),x,y);if(legacyInfoHovered(x,y,10,92,10,10))graphics.renderTooltip(font,Component.translatable("gui.hbm.silex.void"),x,y);}
 @Override public boolean mouseClicked(double x,double y,int button){boolean handled=super.mouseClicked(x,y,button);if(legacyInfoHovered(x,y,10,92,12,12)){minecraft.getSoundManager().play(SimpleSoundInstance.forUI(SoundEvents.UI_BUTTON_CLICK,1));PacketDistributor.sendToServer(new SilexControl(menu.containerId));return true;}return handled;}
}
